import type { Applicability } from './Applicability'

export type UxListApplicability = Now.Internal.WithID<
    {
        active?: boolean
        applicability: Applicability | string
        order?: number
    } & Now.Internal.Meta
>

export type UxList = Now.Internal.WithID<
    {
        /** Whether the list is active and visible to users */
        active?: boolean

        applicabilities?: UxListApplicability[]

        /** Comma-separated list of column names to display in the list (e.g., "number,priority,state,assigned_to,short_description") */
        columns?: string

        /** Encoded query condition to filter records in the list */
        condition?: string

        /** Whether to enable infinite scroll instead of pagination */
        enableInfiniteScroll?: boolean

        /** Fixed query for the list table */
        fixedQuery?: string

        /** Column name to group records by */
        groupByColumn?: string

        /** User groups that can access this list */
        groups?: string

        /** Whether to hide the cell filter option */
        hideCellFilter?: boolean

        /** Whether to hide checkbox on hover */
        hideCheckboxHover?: boolean

        /** Whether to hide column filtering capability */
        hideColumnFiltering?: boolean

        /** Whether to hide column grouping capability */
        hideColumnGrouping?: boolean

        /** Whether to hide column resizing capability */
        hideColumnResizing?: boolean

        /** Whether to hide column sorting capability */
        hideColumnSorting?: boolean

        /** Whether to hide drag and drop functionality */
        hideDragAndDrop?: boolean

        /** Whether to hide the empty state image when no records are found */
        hideEmptyStateImage?: boolean

        /** Whether to hide the first page button in pagination */
        hideFirstPage?: boolean

        /** Whether to hide the list header */
        hideHeader?: boolean

        /** Whether to hide content highlighting */
        hideHighlightContent?: boolean

        /** Whether to hide highlighted values in cells */
        hideHighlightedValues?: boolean

        /** Whether to hide inline editing capability */
        hideInlineEditing?: boolean

        /** Whether to hide the last page button in pagination */
        hideLastPage?: boolean

        /** Whether to hide the last refreshed timestamp text */
        hideLastRefreshedText?: boolean

        /** Whether to hide hyperlinks in cells */
        hideLinks?: boolean

        /** Whether to hide list actions menu */
        hideListActions?: boolean

        /** Whether to hide the menu button */
        hideMenuButton?: boolean

        /** Whether to hide the next page button in pagination */
        hideNextPage?: boolean

        /** Whether to hide the "Save as" option */
        hideOptionToSaveAs?: boolean

        /** Whether to hide page numbers in pagination */
        hidePages?: boolean

        /** Whether to hide pagination controls entirely */
        hidePagination?: boolean

        /** Whether to hide advanced panel options */
        hidePanelAdvanced?: boolean

        /** Whether to hide panel button */
        hidePanelButton?: boolean

        /** Whether to hide condition delete option in panel */
        hidePanelConditionDelete?: boolean

        /** Whether to hide panel footer */
        hidePanelFooter?: boolean

        /** Whether to hide restore option in panel */
        hidePanelRestore?: boolean

        /** Whether to hide personalization options */
        hidePersonalization?: boolean

        /** Whether to hide the previous page button in pagination */
        hidePreviousPage?: boolean

        /** Whether to hide quick edit functionality */
        hideQuickEdit?: boolean

        /** Whether to hide the range display (e.g., "1-20 of 100") */
        hideRange?: boolean

        /** Whether to hide the record count badge */
        hideRecordCountBadge?: boolean

        /** Whether to hide reference field links */
        hideReferenceLinks?: boolean

        /** Whether to hide the refresh button */
        hideRefreshButton?: boolean

        /** Whether to hide the row count display */
        hideRowCount?: boolean

        /** Whether to hide the row selector checkbox */
        hideRowSelector?: boolean

        /** Whether to hide the rows per page selector dropdown */
        hideRowsPerPageSelector?: boolean

        /** Whether to hide the select all checkbox */
        hideSelectAll?: boolean

        /** Whether to hide the sharing button */
        hideSharingButton?: boolean

        /** Whether to hide the list title */
        hideTitle?: boolean

        /** Color to use for highlighting content */
        highlightContentColor?: string

        /** Pattern/regex to match content for highlighting */
        highlightContentPattern?: string

        /** Additional list attributes for customization */
        listAttributes?: string

        /** Configuration for live updates of the list */
        liveUpdates?: string

        /** Maximum number of characters to display in cells before truncating */
        maxCharacters?: number

        /** Sort order of the list within its category */
        order?: number

        /** Whether to override user's word wrap preference */
        overrideWordWrapUserPref?: boolean

        /** Comma-separated list of roles that can access this list */
        roles?: string

        /** Name of the table this list displays records from */
        table: string

        /** Display title of the list */
        title: string

        /** Reference to a specific view to apply to the list */
        view?: string

        /** Whether to enable word wrapping in cells */
        wordWrap?: boolean
    } & Now.Internal.Meta
>

export type UxListCategory = Now.Internal.WithID<
    {
        title: string
        active?: boolean
        order?: number
        description?: string
        lists: UxList[]
    } & Now.Internal.Meta
>

export type UxListMenuConfig = Now.Internal.WithID<
    {
        name: string
        active?: boolean
        description?: string
        categories?: UxListCategory[]
    } & Now.Internal.Meta
>

/**
 * @param config
 * @constructor
 */

export function UxListMenuConfig(config: UxListMenuConfig) {
    return config
}
